// pubspec.yaml:
//   firebase_remote_config: ^4.3.0

import 'package:firebase_remote_config/firebase_remote_config.dart';

Future<void> initRemoteConfig() async {
  final rc = FirebaseRemoteConfig.instance;

  // 1. Baked defaults — app WORKS OFFLINE / first launch.
  await rc.setDefaults({
    'home_variant': 'A',
    'max_cart_items': 20,
    'feature_x_enabled': false,
    'promo_banner_text': 'Welcome!',
    'checkout_layout_version': 2,
    'min_supported_app_version': '1.0.0',
  });

  // 2. Fetch settings — throttled by MIN interval.
  await rc.setConfigSettings(RemoteConfigSettings(
    fetchTimeout: const Duration(seconds: 10),
    minimumFetchInterval: const Duration(hours: 1),  // prod
    // minimumFetchInterval: Duration.zero,           // dev
  ));

  // 3. Fetch + activate (one-shot).
  try {
    final activated = await rc.fetchAndActivate();
    // activated = true if new values were pulled + swapped in.
  } catch (_) {
    // Fetch failure → app still runs on defaults / last-activated.
  }

  // 4. Optional: real-time listener (SDK v3+).
  rc.onConfigUpdated.listen((_) async {
    await rc.activate();
    // notify UI to re-read values (e.g., via Riverpod / Bloc).
  });
}

// ────── Read values anywhere in the app ──────
final rc = FirebaseRemoteConfig.instance;
final variant = rc.getString('home_variant');       // 'A' | 'B' | 'C'
final max = rc.getInt('max_cart_items');            // 20 or overridden
final enabled = rc.getBool('feature_x_enabled');    // false → true when console flips
final banner = rc.getString('promo_banner_text');
final minVer = rc.getString('min_supported_app_version');

// ────── Force-update pattern ──────
if (Version.parse(currentVersion) < Version.parse(minVer)) {
  showBlockingUpdateDialog();
}
